'use strict';
const assert = require('node:assert/strict');
const { createCache } = require('./src/cache');
const tick = () => new Promise(r => setImmediate(r));
function deferred() { let resolve, reject; const promise = new Promise((a, b) => { resolve = a; reject = b; }); return { promise, resolve, reject }; }

(async () => {
  // Repeated invalidations: old flights must neither store nor detach newer flight.
  {
    const gates = [deferred(), deferred(), deferred()];
    let calls = 0;
    const c = createCache({ now: () => 0, load: () => gates[calls++].promise });
    const a = c.get('k'); await tick();
    c.invalidate('k');
    const b = c.get('k'); await tick();
    c.invalidate('k');
    const cc = c.get('k'); await tick();
    gates[1].resolve('B'); assert.equal(await b, 'B');
    const joined = c.get('k'); // must join C, not start a new load
    gates[0].resolve('A'); assert.equal(await a, 'A');
    gates[2].resolve('C');
    assert.equal(await cc, 'C'); assert.equal(await joined, 'C');
    assert.equal(calls, 3); assert.equal(await c.get('k'), 'C'); assert.equal(calls, 3);
  }
  // set wins over old load and its TTL is not restarted; expiry starts new load.
  {
    let t = 0; const g = deferred(); let calls = 0;
    const c = createCache({ now: () => t, ttlMs: 10, load: () => (++calls === 1 ? g.promise : 'new') });
    const old = c.get('k'); await tick();
    c.set('k', 'S');
    t = 5; g.resolve('old'); assert.equal(await old, 'old');
    assert.equal(await c.get('k'), 'S');
    t = 10; assert.equal(c.size, 0);
    assert.equal(await c.get('k'), 'new'); assert.equal(calls, 2);
  }
  // set expires while old load pending -> new load, not detached one.
  {
    let t = 0; const g = deferred(); let calls = 0;
    const c = createCache({ now: () => t, ttlMs: 10, load: () => (++calls === 1 ? g.promise : 'new') });
    const old = c.get('k'); await tick();
    c.set('k', 'S'); t = 10;
    assert.equal(await c.get('k'), 'new'); assert.equal(calls, 2);
    g.resolve('old'); assert.equal(await old, 'old'); assert.equal(await c.get('k'), 'new');
  }
  // Rejections not cached; shared reason; sync throw; non-Error reason; retry works.
  {
    let calls = 0;
    const c = createCache({ now: () => 0, load: () => { calls++; if (calls === 1) throw 'boom'; if (calls === 2) return Promise.reject(null); return 'ok'; } });
    const r1 = c.get('k'), r2 = c.get('k');
    await assert.rejects(r1, x => x === 'boom'); await assert.rejects(r2, x => x === 'boom');
    await assert.rejects(c.get('k'), x => x === null);
    assert.equal(await c.get('k'), 'ok'); assert.equal(calls, 3);
  }
  // Obsolete rejection must not detach newer flight.
  {
    const gates = [deferred(), deferred()]; let calls = 0;
    const c = createCache({ now: () => 0, load: () => gates[calls++].promise });
    const a = c.get('k'); await tick(); c.invalidate('k');
    const b = c.get('k'); await tick();
    gates[0].reject(new Error('x')); await assert.rejects(a);
    const j = c.get('k'); gates[1].resolve('B');
    assert.equal(await j, 'B'); assert.equal(await b, 'B'); assert.equal(calls, 2);
  }
  // Synchronous invalidate/set/clear inside load; self-read joins.
  {
    let calls = 0, inner;
    const c = createCache({ now: () => 0, load: k => { calls++; if (calls === 1) { inner = c.get(k); c.invalidate(k); return 'stale'; } return 'fresh'; } });
    assert.equal(await c.get('k'), 'stale');
    assert.equal(await inner, 'stale');
    assert.equal(await c.get('k'), 'fresh'); assert.equal(calls, 2);
  }
  {
    const c = createCache({ now: () => 0, load: k => { c.set(k, 'S'); return 'L'; } });
    assert.equal(await c.get('k'), 'L'); assert.equal(await c.get('k'), 'S');
  }
  {
    let calls = 0;
    const c = createCache({ now: () => 0, load: () => { calls++; c.clear(); return calls; } });
    assert.equal(await c.get('k'), 1); assert.equal(await c.get('k'), 2); assert.equal(c.size, 0);
  }
  // ttlMs 0: dedup unsettled flight, never reuse settled value; undefined values cached.
  {
    let calls = 0; const c = createCache({ now: () => 0, ttlMs: 0, load: () => ++calls });
    const [x, y] = await Promise.all([c.get('k'), c.get('k')]);
    assert.equal(x, 1); assert.equal(y, 1); assert.equal(await c.get('k'), 2); assert.equal(c.size, 0);
  }
  {
    let calls = 0; const c = createCache({ now: () => 0, load: () => { calls++; return undefined; } });
    await c.get(NaN); assert.equal(await c.get(NaN), undefined); assert.equal(calls, 1); assert.equal(c.size, 1);
  }
  console.log('all scratch checks passed');
})().catch(e => { console.error(e); process.exit(1); });

